def normalize(cells):
 return tuple(sorted((r-min(y for y,x in cells),c-min(x for y,x in cells)) for r,c in cells))
def canon(cells):
 pts=list(cells); variants=[]
 for refl in (1,-1):
  for k in range(4):
   # rotate about origin k times after x reflection
   q=[(r, c*refl) for r,c in pts]
   for _ in range(k): q=[(c,-r) for r,c in q]
   variants.append(normalize(q))
 return min(variants)
