 else: dirs=(-1,-1)
 def interior(cells):return all((r-r0)*dirs[0]>0 and (c-c0)*dirs[1]>0 for r,c in cells)
 inside=[(co,ce) for co,ce in comps if set(ce)!=s and interior(ce)]
